    def test_unexpected_sigterm_flags_offending_event_start(self):
        self.setup_thread(admit=False)
        peer = self.root / "box-peer.md"
        with peer.open("a") as stream:
            stream.write("**COACHED fixture-thread FIX: partial correction**")
        seed = peer.read_text()
        watcher = subprocess.Popen([str(TOOL), "coach", str(self.brief), "--watch"], cwd=self.cwd, env=self.env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True)
        try:
            self.assertIn("waiting for teach-back", watcher.stderr.readline())
            watcher.terminate()
            watcher.wait(timeout=5)
        finally:
            if watcher.poll() is None:
                watcher.kill()
                watcher.wait()
            watcher.stderr.close()
        self.assertIn("observer stopped: signal 15", peer.read_text()[len(seed):])
        self.assertTrue(peer.read_text()[len(seed):].startswith("\nCOACH FLAG "))
        start = self.rollout.stat().st_size
        seed = peer.read_text()
        with self.rollout.open("a") as stream:
            stream.write("{bad\n\n")
        self.append(self.message("later evidence"))
        result = self.command("coach", str(self.brief))
        self.assertNotEqual(result.returncode, 0)
        self.assertIn(f"{self.rollout} {start}: observer stopped:", peer.read_text()[len(seed):])
        self.assertEqual(json.loads((self.state / "fixture-thread.json").read_text())["corrections"], ["partial correction"])

    def test_normal_sigterm_before_admission_records_status(self):
        self.setup_thread(admit=False)
        peer = self.root / "box-peer.md"
        seed = peer.read_text()
        marker = self.state / "worker-exited"
        watcher = subprocess.Popen([str(TOOL), "coach", str(self.brief), "--watch"], cwd=self.cwd, env=dict(self.env, CODEX_LEAD_COACH_WORKER_EXIT=str(marker)), stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True)
        try:
            self.assertIn("waiting for teach-back", watcher.stderr.readline())
            marker.touch()
            watcher.terminate()
            watcher.wait(timeout=5)
        finally:
            if watcher.poll() is None:
                watcher.kill()
                watcher.wait()
            watcher.stderr.close()
        self.assertEqual(peer.read_text(), seed)
        self.assertIn("observer stopped: worker exited", (self.root / "box-status.md").read_text())

    def test_recorded_drift_and_offset_journey(self):
        self.setup_thread()
        drift = {"type": "response_item", "payload": {"type": "custom_tool_call", "name": "apply_patch", "call_id": "seeded-drift", "input": "*** Begin Patch\n*** Add File: outside.py\n+drift\n*** End Patch"}}
        self.append(drift)
        outside = self.cwd / "outside.py"
        drifted = self.command("coach", str(self.brief))
        self.assertEqual(drifted.returncode, 0, drifted.stderr)
        rpcs = [json.loads(line) for line in self.rpc_log.read_text().splitlines()]
        corrections = [r for r in rpcs if r["method"] == "turn/steer" and r["params"]["input"][0]["text"].startswith("Coach correction:")]
        self.assertEqual(len(corrections), 1)
        self.assertEqual(corrections[0]["params"]["expectedTurnId"], "live-turn")
        self.assertEqual(corrections[0]["params"]["threadId"], "fixture-thread")
        self.assertIn("COACHED fixture-thread FIX: Revert", (self.root / "box-peer.md").read_text())
        outside.write_text("drift\n")
        self.assertEqual(self.command("coach", str(self.brief)).returncode, 0)
        self.assertEqual(len(self.inputs()), 2)
        self.append({"type": "response_item", "payload": {"type": "custom_tool_call", "name": "apply_patch", "input": "*** Begin Patch\n*** Delete File: outside.py\n*** End Patch"}})
        self.assertEqual(self.command("coach", str(self.brief)).returncode, 0)
        self.assertEqual(len(self.inputs()), 2)
        outside.unlink()
        self.assertEqual(self.command("coach", str(self.brief)).returncode, 0)
        self.assertEqual(len(self.inputs()), 2)
        self.append(self.message("Reverted outside.py; I will edit owned.py only."))
        self.append({"type": "response_item", "payload": {"type": "custom_tool_call", "name": "apply_patch", "input": f"*** Begin Patch\n*** Update File: {self.test_file}\n+checked\n*** End Patch"}})
        self.append(self.message("I am uncertain about the next input."))
        result = self.command("coach", str(self.brief))
        self.assertEqual(result.returncode, 0, result.stderr)
        observed = [json.loads(item["prompt"].split("\n")[-1]) for item in self.inputs()]
        self.assertIn("Reverted outside.py", json.dumps(observed[-2]["rollout_delta"]))
        self.assertEqual([p["checkpoint"] for p in observed], ["teach-back", "edit outside brief files", "test file write", "blocked or uncertain message"])
        self.assertEqual(result.stdout, "on course\non course\n")
        count = len(self.inputs())
        partial = json.dumps(self.message("Blocked on one input; café."), ensure_ascii=False).encode()
        cut = partial.index("é".encode()) + 1
        with open(self.rollout, "ab") as f:
            f.write(partial[:cut])
        first = self.command("coach", str(self.brief))
        self.assertEqual(first.returncode, 0, first.stderr)
        offset = json.loads((self.state / "fixture-thread.json").read_text())["offset"]
        self.assertEqual(offset, self.rollout.stat().st_size)
        self.assertEqual(len(self.inputs()), count)
        with open(self.rollout, "ab") as f:
            f.write(partial[cut:] + b"\n")
        second = self.command("coach", str(self.brief))
        self.assertEqual(second.returncode, 0, second.stderr)
        delta = json.loads(self.inputs()[-1]["prompt"].split("\n")[-1])["rollout_delta"]
        self.assertEqual([p["payload"]["content"][0]["text"] for p in delta], ["Blocked on one input; café."])
        self.assertEqual(len(self.inputs()), count + 1)
        print("PUBLIC JOURNEY drift detected at checkpoint, actual turn/steer emitted, recorded correction observed; test/uncertain triggers and UTF-8 partial-offset continuation passed")

    def test_sixty_real_recorded_turns(self):
        self.setup_thread()
        rows = json.loads(zlib.decompress(base64.b64decode(RECORDED)))
        self.assertEqual(sum(row["type"] == "token_usage_record" for row in rows), 60)
        for row in rows:
            self.append(row)
        self.append(self.message("Blocked on the final recorded measurement."))
        result = self.command("coach", str(self.brief))
        self.assertEqual(result.returncode, 0, result.stderr)
        inputs = self.inputs()
        actual = [json.loads(item["prompt"].split("\n")[-1]) for item in inputs]
        self.assertIn("model steps", [item["checkpoint"] for item in actual])
        counts = json.loads((self.state / "fixture-thread.json").read_text())["input_tokens"]
        self.assertLess(max(counts), 20000)
        self.assertTrue(all(count == 323 for count in counts))
        self.assertTrue(all(item["args"] == ["-p", "--model", "claude-sonnet-5-5", "--no-session-persistence", "--tools", "", "--strict-mcp-config", "--disable-slash-commands", "--setting-sources", "", "--output-format", "json"] for item in inputs))
        consumed = [row for item in actual for row in item["rollout_delta"] if row["type"] == "token_usage_record"]
